import pg from 'pg';
import { readFileSync, readdirSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { loadDatabaseConfig } from '/app/dist/config.js';
import { databaseConnectionOptions } from '/app/dist/db.js';
if(process.env.CONTENT_KEY_NAMESPACE!=='rillora-production'||process.env.RECOVERY_ENVIRONMENT!=='production')throw Error('Wrong environment');
const db=new pg.Client(databaseConnectionOptions(loadDatabaseConfig()));await db.connect();
try {
 await db.query('begin');await db.query("select pg_advisory_xact_lock(hashtext('rillora_review_catalog_20260930'))");
 const rows=(await db.query('select name,checksum from app.schema_migrations order by name')).rows;
 const files=readdirSync('/app/migrations').filter(x=>/^\d+_[a-z0-9_]+\.sql$/.test(x)).sort();
 if(rows.length!==files.length||!rows.at(-1).name.startsWith('0086_'))throw Error('Wrong migration checkpoint');
 for(const f of files)if(rows.find(x=>x.name===f)?.checksum!==createHash('sha256').update(readFileSync('/app/migrations/'+f)).digest('hex'))throw Error('Migration mismatch');
 const production=(await db.query('select production_entitlements_enabled from app.commerce_runtime_policy')).rows;
 if(production.length!==1||production[0].production_entitlements_enabled!==false)throw Error('Production access unexpectedly enabled');
 const before=(await db.query("select (select count(*)::int from app.planners where status='active') as planners,(select count(*)::int from app.commerce_orders where provider_environment='production') as real_orders,(select count(*)::int from app.commerce_subscriptions where provider_environment='production') as real_subscriptions")).rows[0];
 if(before.real_orders||before.real_subscriptions||before.planners)throw Error('Expected unused closed production database; inspect before changing catalog');
 const prior=(await db.query("select row_to_json(p) as row from app.commerce_prices p where price_code='family_usd_annual_v4'")).rows[0]?.row;
 if(!prior||Number(prior.amount_minor)!==8899)throw Error('Preserve Web88.99');
 await db.query(`insert into app.commerce_prices(price_code,plan_version_id,operator_code,service_market_code,amount_minor,minor_unit_exponent,currency_code,billing_interval,tax_behavior,status,purchase_channel,effective_from)
  select 'family_apple_review_usd_6800_20260930',plan_version_id,operator_code,service_market_code,6800,2,'USD','annual','provider_determined','test_only','apple_app_store',now() from app.commerce_prices where price_code='family_usd_annual_v4' on conflict(price_code) do nothing`);
 await db.query(`insert into app.commerce_apple_price_bindings(binding_code,price_id,product_reference,storefront_country_code,effective_from,status,provider_environment)
  select 'apple_review_usa_6800_20260930',id,'com.rillora.family.annual','USA',effective_from,'active','sandbox' from app.commerce_prices where price_code='family_apple_review_usd_6800_20260930' on conflict(binding_code) do nothing`);
 await db.query(`insert into app.commerce_storefront_products(price_id,provider_code,provider_environment,external_product_reference,provider_account_reference,external_parent_product_reference,storefront_country_code,status,effective_from)
  select p.id,'storekit','sandbox','com.rillora.family.annual','com.rillora.ios','22325627','USA','test_only',p.effective_from from app.commerce_prices p where p.price_code='family_apple_review_usd_6800_20260930' and not exists(select 1 from app.commerce_storefront_products sp where sp.price_id=p.id and sp.provider_environment='sandbox')`);
 await db.query(`insert into app.commerce_purchase_route_policies(policy_code,version,market_policy_id,storefront_policy_id,purchase_route,provider_code,enabled,status,effective_from)
  select 'global_us_ios_review_20260930',1,market_policy_id,storefront_policy_id,'apple_storekit','storekit',true,'test_only',now() from app.commerce_purchase_route_policies where policy_code='global_us_ios_stripe_v1' and version=1 on conflict(policy_code,version) do nothing`);
 await db.query("update app.commerce_plan_versions set status='active' where plan_code='family' and version=2");
 await db.query("update app.commerce_plan_capabilities set enforcement_mode='included' where plan_version_id in(select id from app.commerce_plan_versions where plan_code='family' and version=2)");
 const quote=(await db.query("select p.price_code,p.amount_minor::int,p.status,b.provider_environment,b.storefront_country_code from app.commerce_prices p join app.commerce_apple_price_bindings b on b.price_id=p.id where b.binding_code='apple_review_usa_6800_20260930'")).rows;
 if(quote.length!==1||quote[0].amount_minor!==6800||quote[0].status!=='test_only'||quote[0].provider_environment!=='sandbox')throw Error('Review binding mismatch');
 const after=(await db.query("select row_to_json(p) as row from app.commerce_prices p where price_code='family_usd_annual_v4'")).rows[0].row;
 if(JSON.stringify(prior)!==JSON.stringify(after))throw Error('Web quote changed');
 const policies=(await db.query("select policy_code,enabled,status,provider_code from app.commerce_purchase_route_policies where policy_code in('global_us_ios_review_20260930','global_us_ios_stripe_v1') order by policy_code")).rows;
 if(policies.length!==2||policies.some(p=>p.policy_code==='global_us_ios_stripe_v1'&&p.enabled))throw Error('Unexpected live route');
 await db.query('set local role continuity_auth');await db.query('select identity_reference_sha256 from app.legal_acceptances limit 0');await db.query('reset role');
 await db.query('commit');
 console.log(JSON.stringify({migrationCount:rows.length,lastMigration:rows.at(-1).name,checksumsMatch:true,before,quote,policies,webPriceUnchanged:true,productionEntitlementsEnabled:false,reviewEnrollmentCreated:false}));
} catch(error) {await db.query('rollback');console.error(error.message);process.exitCode=1;}finally{await db.end();}
